use relay.feed;

pub fn publish(io: Io) -> Result<Unit, Error> uses {Io.write} {
    let frames = relay.feed.frames();
    var total = 0;
    var index = 0;

    while index < frames.len() {
        let value = match frames.get(index: index) {
            Some(frame) => match relay.feed.decode(frame) {
                Ok(value) => value,
                Err(_) => 0,
            },
            None => 0,
        };
        total = total + value;
        index = index + 1;
    }

    relay.feed.emit_total(io: io, total: total)?;
    return Ok(unit);
}

