use mill.stock;
use mill.rules;

pub fn lines() -> String {
    var labels: List<String> = [];
    let planks = mill.stock.inventory();
    var index = 0;
    while index < planks.len() {
        let plank = planks.get(index: index)?;
        if mill.rules.is_kept(plank) {
            labels.push(item: mill.rules.label(plank));
        }
        index = index + 1;
    }
    labels.join(sep: ",")
}

