use depot.locker;

fn report() -> String {
    let ax = depot.locker.stow(
        locker: depot.locker.stow(locker: depot.locker.empty(label: "ax"), load: 12),
        load: 9,
    );
    let bay = depot.locker.stow(
        locker: depot.locker.stow(locker: depot.locker.empty(label: "bay"), load: 30),
        load: 25,
    );
    let cod = depot.locker.stow(locker: depot.locker.empty(label: "cod"), load: 5);
    depot.locker.render(locker: ax)
        .concat(other: ",")
        .concat(other: depot.locker.render(locker: bay))
        .concat(other: ",")
        .concat(other: depot.locker.render(locker: cod))
}

