use stable.herd;
use stable.ledger;

fn main(io: Io) -> Result<Unit, Error> uses {Io.write} {
    let lineup = stable.herd.lineup();
    var entries: List<String> = [];
    var i = 0;

    while i < lineup.len() {
        let pony = match lineup.get(index: i) {
            Some(pony) => pony,
            None => ??missing_pony,
        };
        let fed = stable.herd.feed(pony: pony, scoops: 3);
        entries.push(item: stable.ledger.render(pony: fed));
        i = i + 1;
    }

    io.write(text: entries.join(sep: ","))?;
    return Ok(unit);
}

