use harbor.signal;

pub fn entries() -> String {
    let signals = harbor.signal.today();
    var rendered: List<String> = [];
    var index = 0;

    while index < signals.len() {
        let entry = match signals.get(index: index) {
            Some(harbor.signal.Signal.Calm) => "calm",
            Some(harbor.signal.Signal.Gale(speed)) => "gale:".concat(other: speed.to_text()),
            Some(harbor.signal.Signal.Fog(density)) => "fog:".concat(other: density),
            None => "",
        };
        rendered.push(item: entry);
        index = index + 1;
    }

    rendered.join(sep: ";")
}

